// Shim that turns a `defineModule()` object into the WIT-required exports
// (init / dispatch / on-activated / on-deactivated / on-destroyed). This
// file is the JS entry point fed to `jco componentize`.
//
// In a productionized SDK this file would be generated by `hypen build`
// from the user's module file; for the spike it's a hand-written ~50 lines.

import counter from "./counter.mjs";

const enc = new TextEncoder();
const dec = new TextDecoder();

function encodeJson(value) {
  return enc.encode(JSON.stringify(value));
}
function decodeJson(bytes) {
  return JSON.parse(dec.decode(bytes));
}

// ── WIT exports ────────────────────────────────────────────────────────────

export function init(_config) {
  // `_config` (JSON bytes) is the module-instantiation config from the DSL.
  // The counter ignores it. Real modules would `decodeJson(_config)` and
  // seed their state from it.
  return encodeJson(counter.initialState);
}

export function dispatch(stateBytes, action) {
  const state = decodeJson(stateBytes);
  const payload = decodeJson(action.payload);

  const handler = counter.actions[action.name];
  if (!handler) {
    // WIT result<_, string>: throw to indicate Err.
    throw new Error(`unknown action: ${action.name}`);
  }

  // Reducer semantics: handler may return a new state OR mutate in place.
  const returned = handler(state, payload);
  const newState = returned !== undefined ? returned : state;

  return {
    state: encodeJson(newState),
    effects: [],
    emit: [],
  };
}

// Lifecycle hooks the counter doesn't care about. Return a no-op reducer
// output (the engine treats `state: undefined` as "nothing changed").
export function onActivated(_state) {
  return { state: undefined, effects: [], emit: [] };
}

export function onDeactivated(_state) {
  return { state: undefined, effects: [], emit: [] };
}

export function onDestroyed(_state) {
  // result<_, string>: nothing to do, nothing to throw.
}

// Self-describing actions. `Object.keys(counter.actions)` is exactly the
// list because the `defineModule({actions: {...}})` API already keys the
// actions object by name — so the author writes nothing extra.
export function actions() {
  return Object.keys(counter.actions);
}
